INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('af448f5b-58d5-5a82-a498-9964a3522803', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 11, 11, 'ራሱ ምዝምዝ ወርቅ ነው፤'),
  ('5da7d418-1f60-5e4c-a432-64d3f286259c', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 12, 12, 'ዐይኖቹ በሙሉ የውኃ ኵሬ አጠገብ እንዳሉ'),
  ('a5d7b182-2871-50b3-ac29-1fb7f0b80a00', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 13, 13, 'ጕንጮቹ ሽቱን የሚያፈስሱ የሽቱ መደብ ናቸው።'),
  ('5392a2dd-426e-5c07-ade8-e220159a02d3', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 14, 14, 'እጆቹ የተርሴስ ፈርጥ እንዳለባቸው እንደ ለዘቡ የወርቅ ቀለበቶች ናቸው፤'),
  ('ae6360e0-0945-50d8-adc9-4fa41a23de4b', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 15, 15, 'እግሮቹ በምዝምዝ ወርቅ እንደ ተመሠረቱ'),
  ('e8606907-432e-5c04-ad26-168418613130', 'e7974bf9-cb20-5569-aa36-ffa1d036fe76', '097b5782-8b08-5d26-ab79-f2fc3ff66020', 16, 16, 'ጕሮሮው እጅግ ጣፋጭ ነው፥ ሁለንተናውም የተወደደ ነው፤'),
  ('e96cc1c2-e2bc-5e09-a652-d09c5ae3ebab', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 1, 1, 'አንቺ በሴቶች ዘንድ የተዋብሽ ሆይ፥'),
  ('cbb19ae6-effc-5558-aa5d-6680ff962702', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 2, 2, 'ልጅ ወንድሜ በገነቱ መንጋውን ይጠብቅ ዘንድ፥'),
  ('fb72bbdd-0a12-59c6-a543-83e58de8e519', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 3, 3, 'እኔ የልጅ ወንድሜ ነኝ፥ ልጅ ወንድሜም የእኔ ነው፤'),
  ('f39fa367-9e01-584f-ad9b-b169faafcb7d', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 4, 4, 'ወዳጄ ሆይ፥ እንደ ቴርሳ ውብ ነሽ፥'),
  ('3b380010-82ce-56f9-a305-b0e4f41582d7', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 5, 5, 'ዐይኖችሽን ከፊቴ መልሺ፤ እነርሱ አስፈርተውኛልና፤'),
  ('f832a348-ce14-5ce7-abb0-295569525209', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 6, 6, 'ጥርሶችሽ ታጥበው እንደ ወጡ'),
  ('11b9bd0b-0795-5e72-ac7a-31c0a9c39111', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 7, 7, 'ከዝምታሽ በቀር ጕንጮችሽ'),
  ('04a06500-3dc9-5879-a959-1d5d6f65d983', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 8, 8, 'ስድሳ ንግሥታት፥ ሰማንያም ቁባቶች'),
  ('e81ca0ce-718b-52ab-a464-c742b60150e3', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 9, 9, 'ርግቤ መደምደሚያዬም አንዲት ናት፤'),
  ('b43d5bcf-07d3-5d76-a178-209acd62579b', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 10, 10, 'ይህች እንደ ማለዳ ብርሃን የምትጐበኝ፥'),
  ('3149eb82-2a02-5370-ae62-bbf957a535e3', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 11, 11, 'ልጅ ወንድሜየወንዙን ዳር ልምላሜ ያይ ዘንድ'),
  ('a9794842-a935-55ff-a4e8-cf5055fa48b4', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 12, 12, 'በዚያ ጡቶችን እሰጥሃለሁ፥'),
  ('76da3544-bf12-5f3d-afdc-68a0c88aaadb', 'e8a91147-3d41-5b68-a19e-20974774a8b9', '1f9bb705-6f8b-5649-a058-acefaecbbd8e', 13, 13, 'በዚያ ጡቶችን እሰጥሃለሁ፥'),
  ('df6420be-d4a7-5801-a393-b96e95214e9d', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 1, 1, 'አንቺ ሱላማጢስ ሆይ፥ ተመለሽ፥ ተመለሽ፤'),
  ('3fbba291-3706-5a6f-a4b4-3b2ec7d3e117', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 2, 2, 'አንቺ የአሚናዳብ ልጅ ሆይ፥'),
  ('bf348998-9bba-52b3-a66d-2940e0c0e309', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 3, 3, 'እንብርትሽ የወይን ጠጅ እንደማይጐድልበት እንደ ተነጠጠ ጽዋ ነው፤'),
  ('328a8112-b913-5aed-a618-85ee5f8fa848', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 4, 4, 'ሁለቱ ጡቶችሽ እንደ ሁለት መንታ'),
  ('377db252-cb2e-5451-a742-03840f37df12', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 5, 5, 'አንገትሽ እንደ ዝሆን ጥርስ ግንብ ነው፤'),
  ('8d294d9a-d231-5185-a33f-1982790442c6', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 6, 6, 'በራስሽ ላይ ያለው ጠጕርሽ እንደ ቀርሜሎስ ተራራ ነው፤'),
  ('1d75300c-e3b1-59a5-aedd-bee1566b8d01', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 7, 7, 'ወዳጄ ሆይ፥ እንዴት የተዋብሽ ነሽ!'),
  ('a494083f-5a45-5265-a6a9-c24e9e27e593', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 8, 8, 'ይህ ቁመትሽ የዘንባባ ዛፍ ይመስላል፥'),
  ('da40f540-fdcf-5afb-a77f-fb7c88f2d580', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 9, 9, 'ወደ ዘንባባው ዛፍ እወጣለሁ'),
  ('581588e3-fc01-5fc5-a41f-3743dde170a9', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 10, 10, 'ጕሮሮሽም ለልጅ ወንድሜ እየጣፈጠ እንደሚገባ፥'),
  ('4d314475-2db6-568d-ada3-b85a335c0ec8', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 11, 11, 'እኔ የልጅ ወንድሜ ነኝ፥ የእርሱም መመለሻው ወደ እኔ ነው።'),
  ('56b25d48-589d-5b6c-ac65-4abe4f5dba04', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 12, 12, 'ልጅ ወንድሜ ሆይ፥ ና፥ ወደ መስክ እንውጣ፥'),
  ('c5e1c4f0-c266-5235-a076-309428bfb26a', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 13, 13, 'ወደ ወይኑ ቦታ ማልደን እንሂድ፤'),
  ('79b304e8-3660-57c9-ac38-bba02a0996b1', 'eea041b1-9a46-54f6-ac64-28d6243c11a2', '7fd3d579-6084-5141-a0b2-d70174c38743', 14, 14, 'ትርንጎዎች መዓዛን ስጡ፤'),
  ('538c6318-c2a2-58a6-ae2a-f8bda64450a8', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 1, 1, 'ልጅ ወንድሜ ሆይ፥ የእናቴን ጡት ትጠባ ዘንድ ማን በሰጠህ?'),
  ('d3cc521f-2938-5dff-a9d3-c877bea5383e', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 2, 2, 'ይዤ ወደ እናቴ ቤት፥ ወደ ወላጅ እናቴም እልፍኝ ባገባሁህ፥'),
  ('aa851a15-1be5-51b7-a841-98b7fddec17b', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 3, 3, 'ቀኙ ባቀፈችኝ ግራውም ከራሴ በታች በሆነች ነበር።'),
  ('77779104-11b1-59ca-a58f-1bca295e7097', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 4, 4, 'እናንተ የኢየሩሳሌም ቈነጃጅት ሆይ፥'),
  ('345262cb-559d-58ec-a227-b595bfd3d826', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 5, 5, 'በልጅ ወንድምዋ ላይ ተደግፋ እንደ ማለዳ ደምቃና አብርታ የምትወጣ ይህች ማን ናት?'),
  ('cbcb5854-fbcc-5ba8-ac94-6993efb9dc57', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 6, 6, 'እንደ ቀለበት በልብህ፥'),
  ('a045db77-f98e-599d-a440-c866a88ee354', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 7, 7, 'ብዙ ውኃ ፍቅርን ያጠፋት ዘንድ አይችልም፥'),
  ('21000955-9a3f-5e80-a233-835f24f27bd0', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 8, 8, 'እኅታችን ትንሽ ናት፥ ጡትም የላትም፤'),
  ('d4fc681e-d666-5ef2-a494-6ec8bded17ab', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 9, 9, 'እርስዋ ቅጥር ብትሆን የብር ግንብ በላይዋ እንሥራ፤'),
  ('ac15b2ac-f4fc-5c6b-a9c5-24a0707df37f', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 10, 10, 'እኔ ቅጥር ነኝ፥ ጡቶችም እንደ ግንብ ናቸው፤'),
  ('b805fd3c-38c0-5fa5-a657-6f7d7ba34a93', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 11, 11, 'ለሰሎሞን በብኤላሞን የወይን ቦታ ነበረው፤'),
  ('b36c66c1-e5b4-5898-a2ea-86ca0cfba27c', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 12, 12, 'ለእኔ ያለኝ የወይን ቦታ በፊቴ ነው፤'),
  ('2f1ee148-f747-5db9-a573-abd763ab757e', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 13, 13, 'በአትክልቱ ቦታ ሲኖር ሌሎች አዩት፥'),
  ('a3821f8e-734b-5f41-ada9-498c68005714', 'c865aa5c-8e48-5c0d-acc4-541bcc78cd7a', '1139d36c-e13a-597f-afed-15d7b51b10f5', 14, 14, 'ልጅ ወንድሜ ሆይ፥ ፍጠን፤'),
  ('13a9775d-136a-5085-a4bf-69a3e88d84c0', '730219c1-06e4-555e-ad8e-3c4b63425b69', '022f91e2-a891-513c-a362-ab56f7d7caec', 1, 1, 'የጥበብ ሁሉ መገኛዋ ከእግዚአብሔር ዘንድ ነው፥ ለዘለዓለምም ከእርሱ ጋር ናት።'),
  ('98fd4da6-38a1-5412-a450-d08ccb922b84', '730219c1-06e4-555e-ad8e-3c4b63425b69', '022f91e2-a891-513c-a362-ab56f7d7caec', 2, 2, 'የባሕር አሸዋን፥ የዝናም ጠብታን፥ የዘለዓለምነት ቀኖችንስ ማን ቈጠረ?'),
