  ('a86147b7-33f1-5604-ad7f-328659bd0522', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 5, 5, 'አውሬዎችንና ወፎችንም እንዲገዟቸው አደረገ።'),
  ('ffd8e3f6-5996-5837-a59c-81f07eb221c6', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 6, 6, 'ቃልንና አንደበትን፥ ዐይንና ጆሮን፥'),
  ('e9b91c1a-e68f-5290-a7b4-ee53fd98aeac', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 7, 7, 'ጥበብን ማወቅንም አጠገባቸው፤'),
