  ('5542d77d-450b-54e6-aeac-85856c7616ba', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 9, 9, 'ቅዱስ ስሙን ያመሰግኑት ዘንድ።'),
  ('21dc63e2-e9de-5c98-aaa2-3d3047f0f388', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 10, 10, 'የሥራውንም ገናናነት ይናገሩ ዘንድ፥'),
  ('5a97156b-a5cc-5882-a48c-632583a1b112', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 11, 11, 'ጥበብን ሰጣቸው፤'),
  ('d544e561-999d-5897-af39-0b008dfd7430', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 12, 12, 'የዘለዓለም መሐላንም ተማማላቸው፤'),
  ('e8c17a8c-cbed-59a3-a639-3fad6f23be30', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 13, 13, 'ዐይኖቻቸውም የጌትነቱን ገናናነት አዩ።'),
  ('3f0452f8-8fd5-56c3-a7d5-fec0b0dc2d21', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 14, 14, 'የጌትነቱንም ቃል ጆሮቻቸው ሰሙ፥'),
  ('d1b2c988-b7bc-5a80-a046-1dbd99c49076', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 15, 15, 'ከኀጢአት ሁሉ ተጠበቁ አላቸው፤'),
