  ('c3e0032a-2518-5828-a405-5ee8be5dfd3e', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 18, 18, 'እስራኤል ግን የእግዚአብሔር ክፍል ሆነ።'),
  ('b9b5c410-8209-50ae-acaf-66909cb88dfd', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 19, 19, 'ሥራቸውም ሁሉ በፊቱ እንደ ፀሐይ ነው፤'),
  ('bd3170fa-8e9b-57d8-abf2-67df146d81d5', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 20, 20, 'ኀጢአታቸውም ከእርሱ አልተሰወረችም፤'),
  ('5a32c1b8-d307-5b93-a4d3-544136963725', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 21, 21, 'የሰው ምጽዋቱ ከእርሱ ጋራ እንደ ማኅተም ነው።'),
  ('1d5e678b-5da4-52cc-a2c3-99c4428b891c', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 22, 22, 'የሰው ዋጋው እንደ ዐይን ብሌን ትጠበቅለታለች።'),
  ('af5e18a9-bd70-5fa9-a886-33e0a22bb441', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 23, 23, 'ኋላ ተመልሶ ዋጋቸውን ይሰጣቸዋል፤'),
  ('95fd199d-63c2-574d-aa3c-6361327cf619', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '31d87209-4757-5c54-a605-ee685a099d99', 24, 24, 'ነገር ግን ንስሓ የሚገቡበትን መንገድ ሰጣቸው፤'),
  ('25d4093b-a2cb-5557-a51b-ceb3e0bdd7f4', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 1, 25, 'ወደ እግዚአብሔር ተመለስ፥'),
  ('3b7c8704-eec4-5332-a9ea-ee57d624a436', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 2, 26, 'ከበደልህም ወደ እግዚአብሔር ተመለስ፤'),
  ('e7ec7c69-f673-540d-a473-f2634e1d5a4e', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 3, 27, 'በሕይወት ሳሉ እንደሚገዙለት ሰዎች፥'),
  ('49cb95bb-f04a-5239-a402-06dc1744e424', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 4, 28, 'የሞተ ሰውን ግን ንስሓ እንደ ኢምንት አለፈው፤'),
  ('bd242341-3d35-5b56-a313-f6989487ed1c', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 5, 29, 'የእግዚአብሔር ቸርነቱ ታላቅ ነውና፤'),
  ('6b119d18-f0f1-5bd3-a2c2-1b05b15a18e5', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 6, 30, 'ሰው ሟች ስለ ሆነ፥'),
