  ('0bcb3a4f-3fc7-5732-af34-5216484c2e28', '15a01c8a-b0b9-5011-a2a9-32e8cb465478', '7cef9fa7-97f4-5982-ae8c-589cfda06a1b', 8, 32, 'እርሱ የሰማይን ምጥቀት ኀይል ያውቃል፥'),
  ('c62950b2-975d-546b-aadf-edb0d286ec62', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 1, 1, 'ለዘለዓለም ሕያው የሆነ እርሱ ሁሉን በአንድነት ፈጠረ።'),
  ('774545a7-7d2a-5abb-a145-b04e32e82780', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 2, 2, 'እውነተኛ እግዚአብሔር ብቻ ነው።'),
  ('123857c9-523a-536e-abd8-bca3c299343e', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 3, 3, 'ሥራውን ያውቅ ዘንድ ማንንም አላሰናበተውም፤'),
  ('f19486b9-568a-53be-aec9-17936c70fb26', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 4, 4, 'ከሀሊነቱንስ ማን መርምሮ ያውቃል?')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('237c5e23-b747-5807-a930-af91ec8cd37d', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 5, 5, 'መጨመርም የለም፤ መቀነስም የለም፤'),
