  ('2008ee68-ed0e-5019-a80b-e84917d38876', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 10, 10, 'ስለዚህ ነገር እግዚአብሔር ይታገሣቸዋል።'),
  ('56135409-0387-59ae-a3e4-215f636fd01b', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 11, 11, 'ፍጻሜያቸው ክፉ እንደ ሆነ አይቶ ዐወቃቸው፤'),
  ('48b19783-ec3e-526b-af32-ec80c66534da', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 12, 12, 'ሰው ባልንጀራውን ብቻ ይቅር ይላል፥'),
  ('e62cf046-9109-5069-a9a9-bd71087692ca', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '5e3c4449-f100-54e1-aa4f-e61cc42796b9', 13, 13, 'ይቈጣል፥ ይገርፋል፥ ይቅር ይላል፥'),
  ('88f06bdb-5720-59d2-a5f4-d2c78ba964e1', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 1, 14, 'ልጄ ሆይ፥ በደስታህ መካከል ኀዘንን አታስገባ፤'),
  ('d5fda0b7-e2ad-51cf-a292-df0b82827ce5', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 2, 15, 'ዝናም ዋዕይን የሚያቀዘቅዘው አይደለምን?'),
  ('64a743ea-3233-5454-a6b7-12e9fffa1001', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 3, 16, 'እነሆ እንግዲህ ከመስጠት መልካም ቃል አይሻልምን?'),
  ('79389a15-3011-528b-aefd-35ab63548cfb', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 4, 17, 'ንፉግ ልቡናውን ደስ ሳይለው ይሰጣል።'),
  ('2e21c33d-9d8c-5ad3-ac29-5ae535ff8fdf', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 5, 18, 'ሳትናገር ተረዳ፥ ሳትታመምም ዳን።'),
  ('94d6e176-3921-57bf-a647-e7c32c20a762', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 6, 19, 'ሳይፈረድብህ ራስህን መርምር፤'),
  ('8d7a3ad5-7216-53d6-a7f7-6de73d86a74e', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 7, 20, 'ሳትደክም ራስህን አዋርድ፥'),
  ('0e3f0e69-8ba2-5550-a64e-1ef21eb07f29', 'cc8c0c15-c121-5f52-aa96-4f6af5c9b7a0', '40999953-9a61-5015-ac2b-02110a270d0e', 8, 21, 'ስእለትህን ፈጥነህ ስጥ፤'),
