  ('4703af25-387d-5f63-a594-ba448cd4ad6f', '2a9a01a3-91cc-50f4-ad0b-fddfd28e137a', '8cbd57ee-ce1e-54a6-a62b-c65bf1508876', 11, 26, 'እንደ ጠባይህ ካልሆነች ፍታት፤'),
